exercises.solution:
function parseAge(text) {
  try {
    const n = parseInt(text);
    if (Number.isNaN(n)) throw new Error("bad number");
    return n;
  } catch (e) {
    return "not a number";
  }
}
console.log(parseAge("42"));
console.log(parseAge("abc"));

