exercises.solution:
class OutOfStockError extends Error {
  constructor(msg) {
    super(msg);
    this.name = "OutOfStockError";
  }
}
function buy(stock) {
  if (stock === 0) throw new OutOfStockError("none left");
  return "sold!";
}
try {
  console.log(buy(0));
} catch (e) {
  console.log(e.name + ":", e.message);
}
